// Nadia Fitness Dance Studio — v5. Progressive enhancement only: every page already works
// without JavaScript (generated by tools/build.py). This adds theme, burger, timetable filters
// and day tabs, the live "Hoy" board, the call status, the WhatsApp form, print and "Volver".
(function () {
  var root = document.documentElement;
  var dataEl = document.getElementById('nf-data');
  var NF = dataEl ? JSON.parse(dataEl.textContent) : null;
  var params = new URLSearchParams(location.search);
  function each(sel, fn) { Array.prototype.forEach.call(document.querySelectorAll(sel), fn); }
  function minutes(t) { var p = t.split(':'); return +p[0] * 60 + +p[1]; }
  function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }

  // ---------- light / dark: follows the OS until chosen, then remembered ----------
  (function () {
    var KEY = 'nf5-theme', btn = document.querySelector('.theme');
    var media = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
    function stored() { try { return localStorage.getItem(KEY); } catch (e) { return null; } }
    function apply(t) { root.setAttribute('data-theme', t); if (btn) btn.setAttribute('aria-label', t === 'dark' ? 'Cambiar a modo claro' : 'Cambiar a modo oscuro'); }
    apply(stored() || (media && media.matches ? 'dark' : 'light'));
    if (media && media.addEventListener) media.addEventListener('change', function (e) { if (!stored()) apply(e.matches ? 'dark' : 'light'); });
    if (btn) btn.addEventListener('click', function () {
      var t = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      try { localStorage.setItem(KEY, t); } catch (e) {}
      apply(t);
    });
  })();

  // ---------- burger menu ----------
  (function () {
    var btn = document.querySelector('.burger'), menu = document.getElementById('menu');
    if (!btn || !menu) return;
    function set(open) { btn.setAttribute('aria-expanded', String(open)); btn.setAttribute('aria-label', open ? 'Cerrar menú' : 'Abrir menú'); menu.classList.toggle('is-open', open); }
    btn.addEventListener('click', function () { set(btn.getAttribute('aria-expanded') !== 'true'); });
    menu.addEventListener('click', function (e) { if (e.target.closest('a')) set(false); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && menu.classList.contains('is-open')) { set(false); btn.focus(); } });
    document.addEventListener('click', function (e) { if (menu.classList.contains('is-open') && !e.target.closest('.navbar')) set(false); });
  })();

  // ---------- timetable: class filter + day tabs (mobile) ----------
  each('[data-timetable]', function (box) {
    var items = box.querySelectorAll('.tt-item');
    var buttons = box.querySelectorAll('.filter');
    var status = box.querySelector('[data-filter-status]');
    var tabs = box.querySelectorAll('.tt-tab');
    var days = box.querySelectorAll('.tt-day');
    var weekday = new Date().getDay();
    var todayIdx = weekday >= 1 && weekday <= 5 ? weekday - 1 : -1;

    function showDay(i) {
      Array.prototype.forEach.call(tabs, function (t, k) { t.setAttribute('aria-selected', String(k === i)); t.tabIndex = k === i ? 0 : -1; });
      Array.prototype.forEach.call(days, function (d, k) { d.classList.toggle('is-active', k === i); });
    }
    Array.prototype.forEach.call(tabs, function (t, i) {
      if (i === todayIdx) t.querySelector('span').textContent = 'Hoy';
      t.addEventListener('click', function () { showDay(i); });
      t.addEventListener('keydown', function (e) {
        var step = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
        if (!step) return;
        e.preventDefault();
        var n = (i + step + tabs.length) % tabs.length;
        showDay(n); tabs[n].focus();
      });
    });
    showDay(todayIdx >= 0 ? todayIdx : 0);

    function select(id) {
      var n = 0, name = '';
      Array.prototype.forEach.call(items, function (li) { var on = !!id && li.getAttribute('data-class') === id; li.classList.toggle('is-on', on); if (on) n++; });
      Array.prototype.forEach.call(days, function (d) { d.classList.toggle('has-on', !!d.querySelector('.is-on')); });
      Array.prototype.forEach.call(buttons, function (b) { var on = b.getAttribute('data-class') === id; b.setAttribute('aria-pressed', String(on)); if (on) name = b.textContent; });
      box.classList.toggle('is-filtering', !!id);
      if (status) status.textContent = id ? name + ': ' + (n / 2) + ' sesiones a la semana' : '';   // each session is in the table and in the day list
    }
    Array.prototype.forEach.call(buttons, function (b) {
      b.addEventListener('click', function () {
        var id = b.getAttribute('data-class');
        select(b.getAttribute('aria-pressed') === 'true' || !id ? '' : id);
      });
    });
    var pre = params.get('clase');
    if (pre && box.querySelector('.filter[data-class="' + pre + '"]')) select(pre);
  });

  // ---------- "Hoy en el estudio": today's classes, now / next ----------
  each('.today', function (box) {
    if (!NF) return;
    var MONTHS = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
    var title = box.querySelector('.today-date'), list = box.querySelector('.today-list'), fallback = box.querySelector('.today-fallback');
    if (fallback) fallback.remove();
    function forDay(d) { return NF.sessions.filter(function (s) { return s.day === d; }).sort(function (a, b) { return minutes(a.start) - minutes(b.start); }); }
    function render() {
      var now = new Date(), day = now.getDay() - 1, nowMin = now.getHours() * 60 + now.getMinutes();
      var isToday = day >= 0 && day <= 4, items = isToday ? forDay(day) : [];
      var finished = isToday && items.length && items.every(function (s) { return minutes(s.end) <= nowMin; });
      var heading;
      if (!isToday || finished) {
        day = isToday && day < 4 ? day + 1 : 0;
        items = forDay(day);
        heading = isToday && day !== 0 ? 'Mañana, ' + NF.days[day].toLowerCase() : 'El ' + NF.days[day].toLowerCase();
        heading = heading.charAt(0).toUpperCase() + heading.slice(1);
        nowMin = -1;
      } else {
        heading = NF.days[day] + ' ' + now.getDate() + ' de ' + MONTHS[now.getMonth()];
      }
      title.textContent = heading;
      list.innerHTML = '';
      var nextMarked = false;
      items.forEach(function (s) {
        var li = el('li', 'tt-' + s.type), start = minutes(s.start), end = minutes(s.end), state = '';
        if (nowMin >= start && nowMin < end) { li.classList.add('is-now'); state = 'Ahora'; }
        else if (nowMin >= end) li.classList.add('is-past');
        else if (!nextMarked && nowMin >= 0) { state = 'Siguiente'; nextMarked = true; }
        li.appendChild(el('time', null, s.start + '–' + s.end));
        var name = el('span', 't-name', s.name);
        if (s.note) name.appendChild(el('span', 't-note', s.note));
        li.appendChild(name);
        li.appendChild(state ? el('span', 't-state', state) : el('span'));
        list.appendChild(li);
      });
    }
    render();
    setInterval(function () { if (!document.hidden) render(); }, 60000);
  });

  // ---------- "¿Atendemos llamadas ahora?" ----------
  each('[data-call-status]', function (box) {
    if (!NF) return;
    function render() {
      var now = new Date(), d = now.getDay() - 1, m = now.getHours() * 60 + now.getMinutes();
      var today = NF.callHours.filter(function (c) { return c.day === d; })[0];
      var open = !!today && m >= minutes(today.from) && m < minutes(today.to);
      var text;
      if (open) text = 'Ahora atendemos llamadas, hasta las ' + today.to + '.';
      else if (today && m < minutes(today.from)) text = 'Hoy atendemos llamadas de ' + today.from + ' a ' + today.to + '.';
      else {
        var next = null;
        for (var k = 1; k <= 7 && !next; k++) { var dd = (now.getDay() - 1 + k + 7) % 7; next = NF.callHours.filter(function (c) { return c.day === dd; })[0]; }
        if (!next) return;
        // tomorrow's index is today's getDay()
        text = 'Ahora no atendemos llamadas. Llámanos ' + (next.day === now.getDay() ? 'mañana' + (now.getDay() === 0 ? ' lunes' : '') : 'el ' + NF.days[next.day].toLowerCase()) + ' de ' + next.from + ' a ' + next.to + ', o escríbenos por WhatsApp.';
      }
      box.classList.toggle('is-open', open);
      box.textContent = text;
    }
    render();
    setInterval(function () { if (!document.hidden) render(); }, 60000);
  });

  // ---------- contact form → WhatsApp (nothing stored) ----------
  (function () {
    var form = document.getElementById('contact-form');
    if (!form || !NF) return;
    var name = form.elements['contact-name'], err = document.getElementById('contact-name-error');
    var pre = params.get('clase');
    if (pre && form.elements['contact-class'].querySelector('option[value="' + pre + '"]')) form.elements['contact-class'].value = pre;
    function clear() { name.removeAttribute('aria-invalid'); err.hidden = true; }
    name.addEventListener('input', function () { if (name.value.trim()) clear(); });
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (!name.value.trim()) { name.setAttribute('aria-invalid', 'true'); err.hidden = false; name.focus(); return; }
      clear();
      var sel = form.elements['contact-class'], course = sel.value ? sel.options[sel.selectedIndex].text : '';
      var text = '¡Hola! Soy ' + name.value.trim() + '. ' + (course ? 'Me interesa ' + course + '.' : 'Quiero información sobre las clases.');
      var note = form.elements['contact-message'].value.trim(), phone = form.elements['contact-phone'].value.trim();
      if (note) text += ' ' + note;
      if (phone) text += ' Mi teléfono: ' + phone + '.';
      window.open(NF.whatsapp.split('?')[0] + '?text=' + encodeURIComponent(text), '_blank', 'noopener');
    });
  })();

  // ---------- keep the focused element clear of the mobile call bar (rule 11) ----------
  // Browsers do not scroll a partly visible element on focus, so a tall field could stay half under the bar.
  document.addEventListener('focusin', function (e) {
    var bar = document.querySelector('.callbar');
    if (!bar || getComputedStyle(bar).display === 'none' || bar.contains(e.target)) return;
    if (e.target.getBoundingClientRect().bottom > bar.getBoundingClientRect().top) e.target.scrollIntoView({ block: 'nearest' });
  });

  // ---------- print, "Volver", footer year ----------
  each('[data-print]', function (b) { b.addEventListener('click', function () { window.print(); }); });
  each('[data-back]', function (a) {
    a.addEventListener('click', function (e) {
      var ref = document.referrer;
      if (ref && ref.indexOf(location.origin) === 0 && ref !== location.href && history.length > 1) { e.preventDefault(); history.back(); }
    });
  });
  var year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
})();
